// Minimal allocator interface
template <typename T>
struct MyAllocator {
    using value_type = T;
    using pointer = T*;
    using const_pointer = const T*;
    using size_type = std::size_t;
    using difference_type = std::ptrdiff_t;

    MyAllocator() noexcept = default;
    template <typename U> MyAllocator(const MyAllocator<U>&) noexcept {}

    T* allocate(std::size_t n) {
        if (n > std::size_t(-1) / sizeof(T)) throw std::bad_array_new_length();
        if (auto p = std::malloc(n * sizeof(T))) return static_cast<T*>(p);
        throw std::bad_alloc();
    }

    void deallocate(T* p, std::size_t) noexcept { std::free(p); }

    // Optional: construct/destroy (C++17 deprecated, используй construct_at/destroy_at)
    template <typename U, typename... Args>
    void construct(U* p, Args&&... args) { ::new (p) U(std::forward<Args>(args)...); }
    template <typename U> void destroy(U* p) { p->~U(); }
};

// Equality comparison required
template <typename T, typename U>
bool operator==(const MyAllocator<T>&, const MyAllocator<U>&) noexcept { return true; }
template <typename T, typename U>
bool operator!=(const MyAllocator<T>&, const MyAllocator<U>&) noexcept { return false; }

template <typename T>
class ArenaAllocator {
    Arena* arena_; // внешний arena
public:
    using value_type = T;
    ArenaAllocator(Arena* a) noexcept : arena_(a) {}
    template <typename U> ArenaAllocator(const ArenaAllocator<U>& other) noexcept : arena_(other.arena_) {}

    T* allocate(std::size_t n) { return arena_->allocate(n * sizeof(T), alignof(T)); }
    void deallocate(T* p, std::size_t n) noexcept { arena_->deallocate(p, n * sizeof(T)); }

    Arena* get_arena() const noexcept { return arena_; }
};

