#include <ranges>

template <std::ranges::range R>
class ChunkView : public std::ranges::view_interface<ChunkView<R>> {
    R base_;
    std::size_t chunk_size_;
public:
    ChunkView(R base, std::size_t n) : base_(std::move(base)), chunk_size_(n) {}

    class Iterator {
        std::ranges::iterator_t<R> it_, end_;
        std::size_t chunk_size_;
    public:
        using iterator_category = std::input_iterator_tag;
        using value_type = std::ranges::subrange<std::ranges::iterator_t<R>>;
        using difference_type = std::ptrdiff_t;

        Iterator(std::ranges::iterator_t<R> it, std::ranges::iterator_t<R> end, std::size_t n)
            : it_(it), end_(end), chunk_size_(n) {}

        value_type operator*() const {
            auto next = it_;
            std::ranges::advance(next, chunk_size_, end_);
            return {it_, next};
        }
        Iterator& operator++() {
            std::ranges::advance(it_, chunk_size_, end_);
            return *this;
        }
        bool operator==(const Iterator& other) const { return it_ == other.it_; }
    };

    Iterator begin() { return Iterator(std::ranges::begin(base_), std::ranges::end(base_), chunk_size_); }
    Iterator end() { return Iterator(std::ranges::end(base_), std::ranges::end(base_), chunk_size_); }
};

template <std::ranges::viewable_range R>
auto chunk(R&& r, std::size_t n) {
    return ChunkView<std::views::all_t<R>>(std::views::all(std::forward<R>(r)), n);
}

// Использование
