// Generator — lazy sequence
template <typename T>
struct Generator {
    struct promise_type {
        T current_value;
        Generator get_return_object() { return Generator{std::coroutine_handle<promise_type>::from_promise(*this)}; }
        std::suspend_always initial_suspend() { return {}; }
        std::suspend_always final_suspend() noexcept { return {}; }
        void unhandled_exception() { std::terminate(); }
        std::suspend_always yield_value(T value) {
            current_value = std::move(value);
            return {};
        }
        void return_void() {}
    };

    std::coroutine_handle<promise_type> coro_;
    Generator(std::coroutine_handle<promise_type> h) : coro_(h) {}
    ~Generator() { if (coro_) coro_.destroy(); }

    Generator(Generator&& other) noexcept : coro_(std::exchange(other.coro_, nullptr)) {}
    Generator& operator=(Generator&& other) noexcept {
        if (this != &other) { if (coro_) coro_.destroy(); coro_ = std::exchange(other.coro_, nullptr); }
        return *this;
    }

    // Range interface
    struct Iterator {
        std::coroutine_handle<promise_type> coro_;
        Iterator(std::coroutine_handle<promise_type> h) : coro_(h) {}
        Iterator& operator++() { coro_.resume(); return *this; }
        T operator*() const { return coro_.promise().current_value; }
        bool operator==(std::default_sentinel_t) const { return coro_.done(); }
    };
    Iterator begin() { if (coro_) coro_.resume(); return Iterator{coro_}; }
    std::default_sentinel_t end() { return {}; }
};

// Генератор Фибоначчи
Generator<int> fibonacci() {
    int a = 0, b = 1;
    while (true) {
        co_yield a;
        int next = a + b;
        a = b;
        b = next;
    }
}

