template <typename T>
struct Task {
    struct promise_type {
        T value_;
        std::exception_ptr exc_;
        Task get_return_object() { return Task{std::coroutine_handle<promise_type>::from_promise(*this)}; }
        std::suspend_always initial_suspend() { return {}; }
        std::suspend_always final_suspend() noexcept { return {}; }
        void unhandled_exception() { exc_ = std::current_exception(); }
        void return_value(T v) { value_ = std::move(v); }
    };

    std::coroutine_handle<promise_type> coro_;
    Task(std::coroutine_handle<promise_type> h) : coro_(h) {}
    ~Task() { if (coro_) coro_.destroy(); }

    T get() {
        if (coro_ && !coro_.done()) coro_.resume();
        if (coro_.promise().exc_) std::rethrow_exception(coro_.promise().exc_);
        return std::move(coro_.promise().value_);
    }
};

Task<int> async_add(int a, int b) {
    co_await std::suspend_always{}; // simulate async
    co_return a + b;
}

