#include <iterator>

class IntRangeIterator {
    int current_;
public:
    using iterator_category = std::random_access_iterator_tag;
    using value_type = int;
    using difference_type = std::ptrdiff_t;
    using pointer = const int*;
    using reference = const int&;

    IntRangeIterator(int v = 0) : current_(v) {}
    reference operator*() const { return current_; }
    pointer operator->() const { return &current_; }

    IntRangeIterator& operator++() { ++current_; return *this; }
    IntRangeIterator operator++(int) { auto tmp = *this; ++current_; return tmp; }
    IntRangeIterator& operator--() { --current_; return *this; }
    IntRangeIterator operator--(int) { auto tmp = *this; --current_; return tmp; }

    IntRangeIterator& operator+=(difference_type n) { current_ += n; return *this; }
    IntRangeIterator& operator-=(difference_type n) { current_ -= n; return *this; }
    friend IntRangeIterator operator+(IntRangeIterator it, difference_type n) { return it += n; }
    friend IntRangeIterator operator+(difference_type n, IntRangeIterator it) { return it += n; }
    friend IntRangeIterator operator-(IntRangeIterator it, difference_type n) { return it -= n; }
    friend difference_type operator-(IntRangeIterator a, IntRangeIterator b) { return a.current_ - b.current_; }
    reference operator[](difference_type n) const { return current_ + n; }

    bool operator==(const IntRangeIterator& other) const { return current_ == other.current_; }
    auto operator<=>(const IntRangeIterator& other) const = default;
};

class IntRange {
    int begin_, end_;
public:
    IntRange(int b, int e) : begin_(b), end_(e) {}
    IntRangeIterator begin() const { return IntRangeIterator{begin_}; }
    IntRangeIterator end() const { return IntRangeIterator{end_}; }
};

